\small
\begin{tabular}{lcccc}
\toprule
\textbf{Task} & $\boldsymbol{J_{\max}}$ & \textbf{\css{}$=1.0$ CPR} & \textbf{Best Single} & \textbf{Verdict} \\
\midrule
IOI        & 0.307 & $+0.109$ & $+0.029$ & PASS \\
